//! The test kit (decision 0044): the messages the unit tests and the players read and write,
//! generated by the build script from `proto/tests.binpb`, the set protoc wrote of
//! `spec/codecs.proto`, `spec/transcoding-required.proto` and this crate's `proto/codec.proto` and
//! `proto/requiring.proto`, as `bead_protobuf_build` sets Buffa's generator. No API: it is built
//! under the feature `testing` alone, for the tests.

/// The generated messages, by their packages.
#[expect(
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    clippy::restriction,
    missing_docs,
    reason = "Buffa's generated code, which Bead's lint table does not hold"
)]
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/_include.rs"));
}

pub use generated::bead::codecs::v1 as codecs;
pub use generated::bead::test;
pub use generated::bead::transcoding::v1 as transcoding;
